"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type ReactNode, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** What the person decided. `pending` means the card still asks. */
export type ToolDecision = "pending" | "allowed" | "denied";

/** Props for an approval card. Pass `decision` to control it, or `defaultDecision` to let it hold its own state. */
export type ToolApprovalProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "title"> & {
  /** The one action, as a plain sentence: "Send the invoice email to 3 clients". */
  action: string;
  /** What will happen, in enough detail to decide: who, what, how much. */
  details?: ReactNode;
  decision?: ToolDecision;
  defaultDecision?: ToolDecision;
  onDecisionChange?: (decision: ToolDecision) => void;
  /** Runs when the undo time is over. Start the real action here, not on the click, or Undo undoes nothing. */
  onAllow?: () => void;
  onDeny?: () => void;
  /** Seconds the person can take an Allow back. */
  undoSeconds?: number;
};

// Damping 60 is 2 × √900: critically damped, so the card shrinks to its line with no bounce.
const RESIZE: Transition = { type: "spring", stiffness: 900, damping: 60, mass: 1 };
const SWAP: Transition = { duration: 0.2, ease: [0.165, 0.84, 0.44, 1] };
const FADE: Transition = { duration: 0.15 };
const INSTANT: Transition = { duration: 0 };

const BUTTON = cn(
  "relative inline-flex h-9 cursor-pointer touch-manipulation items-center justify-center rounded-full px-4 text-sm font-medium outline-none",
  // The pseudo-element grows the hit area to 44px tall.
  "before:absolute before:inset-x-0 before:-inset-y-1.5",
  "motion-safe:transition motion-safe:duration-150 active:scale-97",
  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card",
);

function Glyph({ kind }: { kind: "ask" | "allowed" | "denied" }) {
  const paths = {
    // A four-point spark: the mark for something the assistant proposes.
    ask: "M8 1 9.8 6.2 15 8 9.8 9.8 8 15 6.2 9.8 1 8l5.2-1.8L8 1Z",
    allowed: "M8 1a7 7 0 1 1 0 14A7 7 0 0 1 8 1Zm3.2 4.7a.75.75 0 0 0-1.05.1L7.2 9.3 5.8 7.9a.75.75 0 1 0-1.06 1.06l2 2a.75.75 0 0 0 1.11-.05l3.45-4.15a.75.75 0 0 0-.1-1.06Z",
    denied: "M8 1a7 7 0 1 1 0 14A7 7 0 0 1 8 1ZM4.75 7.25a.75.75 0 0 0 0 1.5h6.5a.75.75 0 0 0 0-1.5h-6.5Z",
  };
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4 shrink-0">
      <path d={paths[kind]} />
    </svg>
  );
}

/**
 * Asks the person to allow one action an agent wants to take. After the choice
 * the card shrinks to one line that states what was decided. An Allow can be
 * taken back for a few seconds, and the action starts only after that.
 */
export function ToolApproval({
  action,
  details,
  decision,
  defaultDecision = "pending",
  onDecisionChange,
  onAllow,
  onDeny,
  undoSeconds = 5,
  className,
  ...divProps
}: ToolApprovalProps) {
  const [ownDecision, setOwnDecision] = useState(defaultDecision);
  const current = decision ?? ownDecision;
  // Undo exists only for an Allow made here, in this visit, and only until the time runs out.
  const [undoable, setUndoable] = useState(false);
  const [height, setHeight] = useState<number | null>(null);
  const inner = useRef<HTMLDivElement>(null);
  const allowButton = useRef<HTMLButtonElement>(null);
  const undoButton = useRef<HTMLButtonElement>(null);
  const summary = useRef<HTMLDivElement>(null);
  // Focus moves only after a choice made here, never when the card first appears.
  const focusNext = useRef<"allow" | "undo" | "summary" | null>(null);
  const onAllowRef = useRef(onAllow);
  const titleId = useId();
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    onAllowRef.current = onAllow;
  }, [onAllow]);

  useEffect(() => {
    const node = inner.current;
    if (!node || !("ResizeObserver" in window)) return;
    const observer = new ResizeObserver(() => setHeight(node.offsetHeight));
    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    if (!undoable || current !== "allowed") return;
    const timer = window.setTimeout(() => {
      // Undo is about to leave the page; a keyboard user on it would lose their place.
      if (document.activeElement === undoButton.current) focusNext.current = "summary";
      setUndoable(false);
      onAllowRef.current?.();
    }, undoSeconds * 1000);
    return () => window.clearTimeout(timer);
  }, [current, undoable, undoSeconds]);

  // The buttons the person just used are gone after each choice, so focus is
  // placed on what replaced them.
  useEffect(() => {
    const target = { allow: allowButton, undo: undoButton, summary }[focusNext.current ?? "summary"];
    if (focusNext.current !== null) target.current?.focus();
    focusNext.current = null;
  }, [current, undoable]);

  const decide = (next: ToolDecision) => {
    focusNext.current = next === "pending" ? "allow" : next === "allowed" && undoSeconds > 0 ? "undo" : "summary";
    setUndoable(next === "allowed" && undoSeconds > 0);
    if (decision === undefined) setOwnDecision(next);
    onDecisionChange?.(next);
    if (next === "denied") onDeny?.();
    if (next === "allowed" && undoSeconds <= 0) onAllow?.();
  };

  const pending = current === "pending";
  const showUndo = current === "allowed" && undoable;
  const appear = { initial: reduceMotion ? { opacity: 0 } : { opacity: 0, filter: "blur(4px)" }, animate: { opacity: 1, filter: "blur(0px)" } };

  return (
    <div
      {...divProps}
      role="group"
      aria-labelledby={titleId}
      data-decision={current}
      className={cn("w-full rounded-2xl border border-border bg-card text-sm text-foreground", className)}
    >
      <motion.div
        initial={false}
        animate={{ height: height ?? "auto" }}
        transition={reduceMotion || height === null ? INSTANT : RESIZE}
        className="overflow-hidden rounded-2xl"
      >
        <div ref={inner}>
          {pending ? (
            <motion.div key="ask" {...appear} transition={reduceMotion ? FADE : SWAP} className="flex flex-col gap-3 p-4">
              <p id={titleId} className="leading-5 font-medium">
                {action}
              </p>
              {details && <div className="rounded-lg bg-muted px-3 py-2 text-xs leading-5 text-muted-foreground">{details}</div>}
              <div className="flex flex-wrap items-center justify-end gap-x-2 gap-y-3">
                {/* The spark and these words mark the request as the assistant's, not the person's own. */}
                <p className="mr-auto flex items-center gap-1.5 text-xs text-muted-foreground">
                  <Glyph kind="ask" />
                  Asked by the assistant
                </p>
                {/* The two choices wrap as a pair, so a narrow card never strands Allow on a line of its own. */}
                <div className="flex items-center gap-2">
                  <button type="button" onClick={() => decide("denied")} className={cn(BUTTON, "border border-border bg-background hover:bg-muted")}>
                    Deny
                  </button>
                  <button
                    ref={allowButton}
                    type="button"
                    onClick={() => decide("allowed")}
                    className={cn(BUTTON, "bg-primary text-primary-foreground hover:bg-primary/90")}
                  >
                    Allow
                  </button>
                </div>
              </div>
            </motion.div>
          ) : (
            <motion.div key="decided" {...appear} transition={reduceMotion ? FADE : SWAP} className="flex min-h-11 items-center gap-2.5 px-4 py-1">
              <span className="text-muted-foreground">
                <Glyph kind={current} />
              </span>
              {/* A div, not a paragraph: a host style that sets how paragraphs wrap would undo the one-line cut. */}
              <div ref={summary} tabIndex={-1} className="-mx-1 min-w-0 flex-1 truncate rounded-sm px-1 outline-none focus-visible:ring-2 focus-visible:ring-ring">
                <span className="font-medium">{current === "allowed" ? "Allowed" : "Denied"}</span>
                <span id={titleId} className="text-muted-foreground">
                  {`: ${action}`}
                </span>
              </div>
              {showUndo && (
                <button
                  ref={undoButton}
                  type="button"
                  onClick={() => decide("pending")}
                  className={cn(BUTTON, "h-8 shrink-0 border border-border bg-background px-3 hover:bg-muted before:-inset-y-2")}
                >
                  Undo
                  {!reduceMotion && (
                    <motion.span
                      aria-hidden="true"
                      initial={{ scaleX: 1 }}
                      animate={{ scaleX: 0 }}
                      // Linear, because the line stands for the time left.
                      transition={{ duration: undoSeconds, ease: "linear" }}
                      className="absolute inset-x-3 bottom-1 h-0.5 origin-left rounded-full bg-foreground/40"
                    />
                  )}
                </button>
              )}
            </motion.div>
          )}
        </div>
      </motion.div>
      <span role="status" className="sr-only">
        {pending ? "" : `${current === "allowed" ? "Allowed" : "Denied"}: ${action}.${showUndo ? ` Undo is available for ${undoSeconds} seconds.` : ""}`}
      </span>
    </div>
  );
}
